   />

   {error ? <ErrorNotice error={error} onRetry={() => void refetch()} /> : null}
   {isLoading ? <LoadingPanel label="Loading the DOM auditor" /> : null}

   {data ? (
    <>
     <Card>
      <div className="stack">
       <Switch
        id="dominvader-enabled"
        label="Watch pages for the canary"
        checked={data.enabled}
        onCheckedChange={(on) =>
         set.mutate(
